describe('CSV File Import - Record Creation', () => {
  beforeEach(() => {
    cy.visit('/records');
  });

  it('should successfully import records from a valid CSV file', () => {
    // Setup: intercept the API call for file upload
    cy.intercept('POST', '/api/records/import').as('importRecords');

    // Create a valid CSV file content
    const csvContent = 'id,name,email\n1,John Doe,john@example.com\n2,Jane Smith,jane@example.com';
    const file = new File([csvContent], 'records.csv', { type: 'text/csv' });

    // Click the import button and select the file
    cy.get('[data-testid="import-button"]').click();
    cy.get('[data-testid="file-input"]').selectFile(file, { force: true });

    // Click the confirm import button
    cy.get('[data-testid="confirm-import-button"]').click();

    // Wait for the API call
    cy.wait('@importRecords').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
      expect(interception.response.body).to.include('success');
    });

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Records imported successfully');

    // Verify records are displayed in the table
    cy.get('[data-testid="records-table"]').should('be.visible');
    cy.get('[data-testid="record-row"]').should('have.length', 2);

    // Verify the first record has the correct data
    cy.get('[data-testid="record-row"]').first().within(() => {
      cy.get('[data-testid="record-name"]').should('contain', 'John Doe');
      cy.get('[data-testid="record-email"]').should('contain', 'john@example.com');
    });

    // Verify the second record has the correct data
    cy.get('[data-testid="record-row"]').eq(1).within(() => {
      cy.get('[data-testid="record-name"]').should('contain', 'Jane Smith');
      cy.get('[data-testid="record-email"]').should('contain', 'jane@example.com');
    });
  });

  it('should handle invalid CSV files and display error messages', () => {
    // Setup: intercept the API call
    cy.intercept('POST', '/api/records/import').as('importRecords');

    // Create an invalid CSV file (missing headers, malformed data)
    const invalidCsvContent = 'id,name\n1,John Doe\ninvalid-row';
    const file = new File([invalidCsvContent], 'invalid.csv', { type: 'text/csv' });

    // Click the import button and select the invalid file
    cy.get('[data-testid="import-button"]').click();
    cy.get('[data-testid="file-input"]').selectFile(file, { force: true });

    // Click the confirm import button
    cy.get('[data-testid="confirm-import-button"]').click();

    // Wait for the API call
    cy.wait('@importRecords').then((interception) => {
      expect(interception.response.statusCode).to.equal(400);
      expect(interception.response.body).to.include('validation_error');
    });

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Invalid CSV format');

    // Verify no records were added
    cy.get('[data-testid="records-table"]').should('be.visible');
    cy.get('[data-testid="record-row"]').should('not.exist');

    // Verify the import button is still enabled for retry
    cy.get('[data-testid="import-button"]').should('not.be.disabled');
  });
});
